INSERT  IGNORE INTO `tbl_emailtemplates_backup` (`id`, `type`, `name`, `subject`, `message`, `fromname`, `fromemail`, `disabled`, `custom`, `language`, `copyto`, `plaintext`, `for_reseller`, `template_variable`, `newsletter_default`, `scheduled`, `mailserv`, `layoutid`) VALUES (1,'general','Registration Confirmation (Manual)','{$companyname} Account Registration','<p> Dear {$username}</p>\r\n<p></p>\r\n<p>Thank you for your interest in {$companyname}.</p>\r\n<p></p>\r\n<p>In order to complete activation on your account a representative will contact you shortly to adjust your account accordingly.</p>\r\n<p>If you wish to complete activation sooner you may send us an email to {$adminmail} (subject title : ACTIVATE ACCOUNT).</p>\r\n<p>In the email please provide your Username and we will complete the process for you so you can start ordering immediately.</p>\r\n<p></p>\r\n<p>{$adminsignature}</p>','','','0','','','',0,1,'',0,0,'',0),(2,'general','Registration Confirmation (Automatic)','{$companyname} Account Registration','<p>Dear {$username}</p>\r\n<p>Thank you for your interest in {$companyname}.</p>\r\n<p>In order to continue registering your details, please click the following link: ===========================================</p>\r\n<p>{$link}</p>\r\n<p>===========================================</p>\r\n<p>If you did not register for this service...</p>\r\n<p>This email has been sent to you because a {$companyname} account has been created using this email address. If you did not register for this service, please contact Customer Support at the following address: {$adminmail} We look forward to seeing you in the world of {$companyname}</p>\r\n<p>{$adminsignature}</p>','','','0','','','',0,1,'{$link}-Account activation link',0,0,'',1),(3,'general','Password Reset Request','{$companyname} - Reset Password','     \r\nDear {$username}  \r\n\r\nSomeone has requested that the password for your account, be reset.\r\n\r\nIf you did not make this request, please simply disregard this e-mail.\r\n\r\nIt is sent only to the address on file for your account and will become invalid after 48 hours, so you do not have to worry about your account being taken over.  \r\n\r\nPlease go to the following URL  :  \r\n=================================\r\n\r\n{$link} \r\n\r\n=================================\r\n\r\n\r\n{$adminsignature}   ','','','0','','','',1,1,'{$link}-Password Reset link',0,0,'',4),(4,'general','Successful Password Change Confirmation','{$companyname} - Password change','<p>Dear {$username}</p>\r\n<p></p>\r\n<p>Your password for our log in system has been successfully changed.</p>\r\n<p>The new password is not printed here to protect your privacy and your user name is confirmed below.</p>\r\n<p style=\"padding-left: 60px;\">=============================</p>\r\n<p style=\"padding-left: 60px;\">Username : {$username}</p>\r\n<p style=\"padding-left: 60px;\">Password : ***HIDDEN***</p>\r\n<p style=\"padding-left: 60px;\">=============================</p>\r\n<p>If you have not requested this change, your account most likely has already been compromised. You should immediately contact us.</p>\r\n<p></p>\r\n<p>{$adminsignature}</p>','','','0','','','',0,1,'',0,0,'',0),(5,'general','Account block notice','Your account has been blocked','  \r\nYour account has been blocked due to \r\n\r\n===============================\r\n\r\n{$blockreson}\r\n\r\n===============================\r\n\r\n{$adminsignature} ','','','','','','',1,1,'{$blockreson}-Account block Reason',0,0,'',0),(6,'imeiorder','IMEI Order Cancelled ','Order Processing Failure','     \r\nDear {$username}\r\n\r\nYour order for {$service} - {$imei} has processing failure .\r\nReason  :  {$reason}  \r\n\r\n\r\n\r\n{$adminsignature}   ','','','0','','','',1,1,'{$service}- Service name,\r\n{$imei}- IMEI,\r\n{$reason}- Order Cancel Reason',0,0,'',0),(7,'general','Successful Security Question Confirmation ','{$companyname} - Security Question Change','    \r\nDear {$username}\r\n\r\nYour security question for our log in system has been successfully changed.\r\nThe new password is not printed here to protect your privacy and your user name is confirmed below.\r\n\r\n===========================\r\n\r\nUsername : {$username}\r\nPassword  : ***HIDDEN***\r\n\r\n===========================\r\n\r\n\r\nIf you have not requested this change, your account most likely has already been compromised.  You should immediately contact us.\r\n\r\n\r\n{$adminsignature}   ','','','','','','',1,1,'',0,0,'',0),(8,'general','Account balance Created / Debited Conformation','Your Account balance updated','             \r\nDear {$username}\r\n\r\nThank you for funding your {$companyname}  account .\r\n\r\n==============================================\r\n{if  $creditadded}Credit Added in Your Account : {$creditadded} \r\n==============================================\r\n{/if} \r\n{if  $creditrebated}Credit Rebated From Your Account : {$creditrebated}\r\n==============================================\r\n{/if}\r\n{if  $sellcreditadded} Sell Credit Added in Your Account : {$sellcreditadded}\r\n==============================================\r\n{/if}\r\n{if  $sellcreditrebated} Sell Credit Rebated From Your Account : {$sellcreditrebated}\r\n==============================================\r\n{/if}\r\n\r\nAccount balance after Funding : {$credit.credit}\r\n{if $sellcreditadded or $sellcreditrebated} Total Available Sell Credit : {$credit.selling_limit}  {/if}\r\n\r\n==============================================\r\n{$usernote}\r\nTransaction ID {$transactionid}\r\n\r\n\r\n{$adminsignature}          ','','','0','','','',1,1,'{$creditadded}-Added new credit,\r\n{$sellcreditadded}- Added new sell credit,\r\n{$creditrebated}-Rebated Credit,\r\n{$sellcreditrebated}-Rebated Sell credit,\r\n{$credit.selling_limit}-Sell Credit Limit ',0,0,'',0),(9,'general','Welcome Email','Welcome to {$companyname}','  \r\nDear {$username}\r\n\r\nThank you for signing up for a {$companyname} account.\r\n\r\nYou will find a copy of your registration details below and a link to the terms which apply to your registration. Please print these off and keep in a safe place for future reference.\r\n\r\n==========================\r\nRegistration details (please keep safe)\r\nUsername : {$username}\r\nPassword   : {if $password_uncrypt} {$password_uncrypt} {else} **HIDDEN** {/if}       \r\nMaster Pin  : {$pin}\r\n==========================\r\n\r\nYou will need to enter your Username and Password whenever you use your {$companyname} account.\r\n\r\nTo review or update your registration details, sign in to your {$companyname} account on a {$siteaddress} .\r\n\r\n{$adminsignature}         ','','','0','','','',1,1,'{$password_uncrypt}- Unencrypted Password',0,0,'',0),(10,'general','Password Reset by Admin','{$companyname} - Your access information','<p>Dear {$username}</p>\r\n<p> </p>\r\n<p> </p>\r\n<p>You have requested your password.</p>\r\n<p> </p>\r\n<p>=======================</p>\r\n<p>Your login data is:</p>\r\n<p>Your New Password is : {$password}</p>\r\n<p>=======================</p>\r\n<p>{$adminsignature}</p>','','','0','','','',0,1,'{$password}-User Password',0,0,'',0),(11,'general','API Access Details','{$companyname} - APi access information','<p>Dear {$username}</p>\r\n<p>The remote API allows you to request codes, get account information and check the status of your orders without having the need to login to the our site.</p>\r\n<p>This allows you to integrate your own site with ours.</p>\r\n<p>We have made our remote API interface relatively simply to use so anyone with any a little XML and PHP experience should be able to implement and develop a system to use on their site.</p>\r\n<p>You can also Download Api document : {$siteaddress}api.zip</p>\r\n<p>=======================================</p>\r\n<p>Your API Access Key : {$apiaccesskey}</p>\r\n<p>=======================================</p>\r\n<p>{$adminsignature}</p>','','','0','','','',0,0,'{$apiaccesskey} - API Access Key',0,0,'',0),(14,'imeiorder','IMEI Order success notification','Your unlock code','          \r\nDear {$username}\r\n\r\nYour unlock code for your mobile phone IMEI : {$imei} has successfully been calculated.\r\n{if  $comments}** {$comments}{/if}\r\n\r\n=================================\r\nUnlock code :  {$reply}\r\n=================================\r\nOrders details\r\nOrder ID : {$orderid}\r\nService Name : {$service}\r\nCredit : {$ordercredit}\r\n{if $model} Model : {$model}{/if}\r\n{if $provider}Provider : {$provider}{/if}\r\n{if $mep}MEP : {$mep}{/if}\r\n{if $pin}PIN  : {$pin}{/if}\r\n{if $kbh}KBH : {$kbh}{/if}\r\n{if $prd}PRD : {$prd}{/if}\r\n{if $type}Type : {$type}{/if}\r\n{if $reference}Reference  :  {$reference}{/if}\r\n{if $locks}Locks  :  {$locks}{/if}\r\n{foreach from=$custom key=id item=cst}\r\n{if $cst.value}{$cst.name} : {$cst.value}{/if}\r\n{/foreach}\r\n\r\n=================================\r\n\r\n\r\n\r\n{$adminsignature}    ','','','0','','','',1,1,'{$orderid}- Order ID , {$imei} - IMEI No, {$note} - Notes , {$comments} - Comments , {$ordercredit} - Credit For Order , {$model} - Model Name , {$provider} - Provider Name , {$mep} - MEP , {$pin} - PIN Number , {$kbh} - KBH , {$prd} - PRD , {$type}- Type ,{$reference} - Reference , {$locks} - Locks ,{$comments}- User Comments,\n{$reply}- Admin Reply',0,0,'',0),(15,'general','orders send to supplier','{$companyname} - New orders','<p>You got new orders from {$companyname}</p>\r\n<p>Orders file has been attached below .</p>\r\n<p>{$orderlist}</p>\r\n<p><br />{$adminsignature}</p>','','','0','','','',0,0,'',0,0,'',0),(16,'fileorder','File Order success','Order calculated successfully','                \r\nDear {$username}\r\n\r\nYour order for {$service} has successfully been calculated.\r\n{if  $comments}** {$comments}{/if}\r\n\r\n===========================\r\n{if $reply} Code :  {$reply}     {else} Your file is attached here . {/if}   \r\n===========================\r\n\r\nOrders details\r\nService : {$service}\r\nCredit : {$ordercredit}\r\n{foreach from=$custom key=id item=cst}\r\n{if $cst.value}{$cst.name} : {$cst.value}{/if}\r\n{/foreach}\r\n\r\n===========================\r\n\r\n\r\n\r\n{$adminsignature}        ','','','0','','','',1,1,'{$service}- Service Name, {$ordercredit} - Credit of Order,{$notes} - Notes , {$comments} - Comments',0,1,'',0),(17,'serverorder','Server Order successfull','Order calculated successfully','            \nDear {$username}\n\nYour order for {$service} has successfully been calculated.\n{if  $comments}** {$comments}{/if}\n\n===========================\n{$reply}\n===========================\nOrders details\nService  : {$service}\nCredit : {$ordercredit}\n{foreach from=$custom key=id item=cst}\n{$cst.name} :  {$cst.value}\n{/foreach} \n\n===========================\n\n\n\n{$feedbacklink}\n\n\n{$adminsignature}     ','','','0','','','',1,1,'{$service}- Service Name, {$ordercredit} - Credit of Order,{$notes} - Notes , {$comments} - Comments,\r\n{$feedbacklink}-Order feedback link',0,0,'',0),(31,'invoice','invoice generated','Invoice #{$invoiceid}','Dear {$username}\r\n\r\nThis is a notice that an invoice #{$invoiceid} has been generated.\r\n\r\n\r\n\r\n{$adminsignature}','','','','','','',1,1,'{$invoiceid}- Invoice Number',0,0,'',0),(30,'invoice','Payment received confirmation','Payment received confirmation','Dear {$username}  \r\n\r\n\r\nPayment received confirmation .\r\nThank you for payment .\r\nInvoice : {$invoice}\r\nAmount  : {$payment}\r\n\r\n\r\n\r\n\r\n{$adminsignature}    ','','','0','','','',1,1,'',0,0,'',0),(46,'newsletter','Monthly News Letter ','Monthly News Letter ','New Services\r\n\r\nPrice Down\r\n\r\nOffers ','','','0','','','',1,0,'',0,0,'',0),(38,'invoice','First Notification for Unpaid Invoice','First Invoice Overdue Notice','Dear {$user}\r\n\r\n           This is a billing notice that your invoice no. {$invid} is now overdue.\r\n\r\n\r\n{$adminsignature}  ','','','','','','',1,1,'{$invid}-Invoice ID',0,0,'',0),(39,'invoice','Second Notification for Unpaid Invoice','Second Invoice Overdue Notice',' Dear {$user}\r\n\r\n           This is the second billing notice that your invoice # {$invid} is now overdue.\r\n\r\n\r\n{$adminsignature}   ','','','','','','',1,1,'{$invid}-Invoice Number',0,0,'',0),(40,'invoice','Third Notification for Unpaid Invoice','Third Invoice Overdue Notice','Dear {$user}\r\n\r\n           This is the third and final billing notice that your invoice # {$invid} is now overdue. \r\n\r\n\r\n{$adminsignature}     ','','','0','','','',1,1,'{$invid}-Invoice Number',0,0,'',0),(41,'general','We are Missing','{$companyname} Missing you','     \r\nDear {$username}\r\n\r\n        From last long time you are not appear on our site , can i help you with price or any matter ?\r\n\r\n{$adminsignature}  ','','','0','','','',1,1,'',0,0,'',0),(42,'general','Low credit limit','URGENT: Low balance in your Account ','    \r\nDear {$username}\r\n\r\nThis is to notify you that Funds under your Reseller account have dropped below your threshold level of USD 10 You are advised to immediately remit funds so that your Customers/Sub-Resellers and you can continue to place Orders. Please follow the process below for adding funds to your account.\r\n\r\n1. Login to : {$siteaddress}\r\n\r\n2. Click on Add Funds \r\n\r\n\r\n{$adminsignature}   \r\n\r\n\r\n\r\n','','','','','','',1,1,'',0,0,'',0),(43,'general','Credit validity expires','Credit validity expiration period is near','  Dear {$username}\r\n\r\nPlease update your credit expiration time .\r\n\r\n\r\n{$adminsignature}     ','','','0','','','',1,1,'',0,0,'',0),(44,'fileorder','File Order Cancelled','Order Processing Failure','        \r\nDear {$username}\r\n\r\nYour order for {$service}  has processing failure .\r\nReason  :  {$reason}  \r\n\r\n\r\n\r\n{$adminsignature}      ','','','','','','',1,1,'{$service}- Service Name,\r\n{$reason}- Order failure reason',0,1,'',0),(45,'serverorder','Server Order Cancelled','Order Processing Failure','       \r\nDear {$username}\r\n\r\nYour order for {$service} has processing failure .\r\nReason  :  {$reason}  \r\n\r\n\r\n\r\n{$adminsignature}     ','','','','','','',1,1,'{$service}- Service Name,\r\n{$reason}- Order failure reason',0,1,'',0),(49,'product','Send shipping details','Your order has been shipped','              \r\nDear {$username}\r\n\r\n\r\nYour order has been shipped by {$shipping_gatway}  and your tracking id  {$trackinid}\r\nTracking URL : {$trackingurl}\r\n\r\n=================================\r\nOrders details\r\nOrder ID : {$orderid}\r\nItem : {$service}\r\n\r\n\r\n{foreach from=$custom key=id item=cst}\r\n{if $cst.value}{$cst.name} : {$cst.value}{/if}\r\n{/foreach}\r\n\r\n=================================\r\n\r\n{$feedbacklink}\r\n\r\n{if $link}\r\nClick on this {$link} to give your feedback\r\n{/if}\r\n{$adminsignature}     ','','','0','','','',1,1,'{$trackinid}-Order Tracking ID,\r\n{$trackingurl}-Shipping order tracking URL,\r\n{$orderid}- Order ID,\r\n{$service}-Item Name,\r\n{$feedbacklink}-Order Feedback link',0,0,'',0),(50,'product','Shop Order Rejected','Your Shopping Order Rejected','      \r\nDear {$username}\r\n\r\nYour order for {$service} has processing failure .\r\nReason  :  {$reason}  \r\n\r\n\r\n** refund amount credited in your account **\r\n\r\n\r\n{$adminsignature}  ','','','','','','',1,1,'{$service}-Item or Service Name,\r\n{$reason}-Order failure reason',0,0,'',0),(51,'general','Security Warning [Country login mismatch]','Security Warning [Country login mismatch]','     \r\nDear {$username}\r\n\r\nWe have detected a suspicious activity on your account.\r\n\r\nIf you are not login from {$loginip} - {$logincountry}({$logincountrycode}) please contact us as soon as possible.\r\nYou may be victim of account theft, and we need to check your security.\r\n\r\n\r\nWe apologize for the hitch and hope you understand this is to better protect your account.   \r\n\r\n\r\n{$adminsignature}  ','','','0','','','',1,0,'{$loginip}- Login IP,\r\n{$logincountry}- Login Country,\r\n{$logincountrycode}- Login Country Code',0,0,'1',0),(52,'general','Subscription Start notice','Your Subscription for {$type}','   \r\nDear {$username}\r\n\r\n         Your Subscription is now activated for service {$type} from today {$subscription_start} and will expired on {$subscription_end} after  {$days} days .\r\n\r\n{$adminsignature}\r\n      ','','','','','','',1,1,'{$type} - Service Name,\r\n{$subscription_start} - Subscription Start Date,\r\n{$subscription_end} - Subscription End Date,\r\n{$days} - No of days between subscription start and end',0,0,'',0),(53,'general','Subscription expired','Your subscription expired today','      \r\nDear {$username}\r\n\r\n          Your Subscription for {$type} is expired today . for renew please contact us .\r\n\r\n{$adminsignature}  ','','','','','','',1,1,'{$type} - Service Name,\r\n{$subscription_start} - Subscription Start Date,\r\n{$subscription_end} - Subscription End Date,\r\n{$days} - No of days between subscription start and end',0,0,'',0),(54,'general','Subscription Reminder','Subscription Expiry Reminder',' \r\nDear {$username}\r\n\r\n             Your subscription for {$type} expired on {$subscription_end} , Please contact your supplier to renew it .\r\n\r\n{$adminsignature}','','','','','','',1,1,'{$type} -Subscribed service name,\r\n{$subscription_start} - Subscription Start Date,\r\n{$subscription_end} - Subscription End Date,\r\n{$days} - No of days between subscription start and end',0,0,'',0),(55,'general','Security Warning [ Common ]','Security Warning From {$companyname}','  \r\nDear {$username}\r\n\r\n This is a security notice to let you know that the following event occurred on your account: \r\n ========================\r\n {$event} \r\n ========================\r\n\r\n If you did not initiate this event, please contact us as soon as possible.\r\n You may be victim of account theft, and we need to check your security.\r\n\r\n {$adminsignature}   ','','','','','','',1,0,'{$event} - Perticular events information when this sercurity mail generated ',0,0,'',0),(56,'general','New Maser Pin','New Maser Pin for {$companyname}','   \r\nDear {$username}\r\n \r\nYour Master Pin is updated , \r\n=======================\r\nYour new master pin is : {$masterpin} \r\n=======================\r\n\r\n{$adminsignature}   ','','','','','','',1,0,'{$masterpin} - Master Pin number',0,0,'',0),(76,'imeiorder','New order placed','New IMEI order placed from your account','  Dear {$username}\r\n\r\n\r\n       New order of {$service} placed from your account \r\n \r\n{$imeilist}\r\n\r\n{$adminsignature}  ','','','0','','','',1,0,'',0,0,'',0),(69,'invoice','Invoice Transaction Refund','Your Refund for Invoice : {$invoiceid}','Dear {$username}\r\n\r\nYour account refunded with amount {$amount} for Invoice : {$invoice}\r\n\r\n ','','','0','','','',1,0,'',0,0,'',0),(57,'supportticket','New ticket open','{$subject}','  \n====================REPLY ABOVE THIS LINE====================\n\nDear {$username},\n\nThank you for contacting our support team. A support ticket has now been opened for your request. You will be notified when a response is made by email. The details of your ticket are shown below.\n\nSubject: {$ticketsubject}\nStatus: Open\n\nYou can view the ticket at any time at {$viewticketlink}\n\n{$adminsignature}\n  ','','','','','','',1,0,'{$ticketsubject}-Ticket subject,{$viewticketlink}-View ticket link ',0,0,'',0),(58,'supportticket','Reply ticket','{$subject}','   \r\n====================REPLY ABOVE THIS LINE====================\r\n\r\n{$ticketreply}\r\n\r\n\r\n\r\n======================================================================\r\nTicket ID: #{$ticketid}\r\nSubject: {$ticketsubject}\r\nStatus: Answered\r\nTicket URL: {$viewticketlink}\r\n======================================================================\r\n\r\n\r\n{$staffsignature}\r\n\r\n{$adminsignature}   ','','','','','','',1,0,'{$ticketreply}- Reply of staff,{$ticketid}-Ticket ID,{$ticketsubject}-Ticket Subject,{$viewticketlink}- View ticket Link on site,{$staffsignature}- Answered staff signature\r\n',0,0,'',0),(59,'product','When Resellers User complete order','Your User made order successfully',' Congratulation ,\r\n\r\n\r\n             Your User placed order and payment completed . \r\n\r\n             And your commission {$amount} credited in your account.\r\n\r\n\r\n\r\n\r\n\r\n{$adminsignature}','','','','','','',1,0,'{$amount}-Amount of order placed by resellers user',0,0,'',0),(60,'supportticket','Ticket auto closed','Your Ticket [{$ticketid}] closed',' Dear {$username}\r\n\r\n           Your Ticket {$ticketid} closed automatically  because not replied from last {$hours} hours\r\n \r\n               \r\n             ','','','','','','',1,0,'{$ticketid}-Support Ticket Id,{$hours}-No of hours before closed',0,0,'',0),(61,'affiliate','Affiliate Commission ','Congratulation your User has made order','<p>Congratulations! You have been credited referral amount {$commission} for your referral.<br /><br /><br />======================================</p>\r\n<p>SIGNUP DETAILS<br />Username : {$username}<br />Product : {$product}<br />======================================<br /><br /><br />Referring from page: <a href=\"http://dhru.com/\" target=\"_blank\" rel=\"noopener\">http://yourwebsite.com/</a><br /><br />You can login to your affiliate management center at : System Uri<br />to see your affiliate conversion statistics and pending payments.<br /><br /><br /><a style=\"text-decoration: none;\">{$adminsignature}</a></p>','','','0','0','','',0,0,'{$commission}-Referral commission amount,\r\n{$username}-Registered Username,\r\n{$product}-Purchased Product',0,0,'',0),(62,'resellerstore','Add fund Error','You havent sufficient balance','Dear {$username}\r\n\r\n \r\n\r\nYour user {$user} has pay you by Paypal\r\n\r\nAmount : {$amount}\r\n\r\nTransaction ID : {$transactionid}\r\n\r\n \r\n\r\nBut you haven\'t sufficient balance so pls complete process manually\r\n\r\n \r\n\r\n{$adminsignature}','','','0','','','',1,0,'{$amount}-Amount Transffered,\r\n{$transactionid}-Transaction ID',0,0,'',0),(63,'resellerstore','Add Fund success','User made payment','Dear {$username}\r\n\r\n \r\n\r\n{$user} has made payment by paypal to your account for add fund\r\n\r\n \r\n\r\n==============================\r\n\r\nAmount : {$amount}\r\n\r\n==============================\r\n\r\n \r\n\r\n \r\n\r\n{$adminsignature}','','','0','','','',1,0,'{$amount}- Fund amount',0,0,'',0),(64,'imeiorderbulk','Bulk reply in single mail','Your unlock code','  Dear {$username}\r\n\r\nYour unlock code has been successfully calculated.\r\n\r\n{foreach from=$replyarry item=reply}\r\n =================================\r\nIMEI : {$reply.imei}\r\nUnlock code :  {$reply.reply}\r\nOrders details\r\nOrder ID : {$reply.orderid}\r\nService Name : {$reply.service}\r\nCredit : {$reply.ordercredit}\r\n{if $reply.model} Model : {$reply.model}{/if}\r\n{if $reply.provider}Provider : {$reply.provider}{/if}\r\n{if $reply.mep}MEP : {$reply.mep}{/if}\r\n{if $reply.pin}PIN  : {$reply.pin}{/if}\r\n{if $reply.kbh}KBH : {$reply.kbh}{/if}\r\n{if $reply.prd}PRD : {$reply.prd}{/if}\r\n{if $reply.type}Type : {$reply.type}{/if}\r\n{if $reply.reference}Reference  :  {$reply.reference}{/if}\r\n{if $reply.locks}Locks  :  {$reply.locks}{/if}\r\n{foreach from=$reply.custom key=id item=cst}\r\n{if $cst.value}{$cst.name} : {$cst.value}{/if}\r\n{/foreach}\r\n\r\n{if  $reply.comments}** {$reply.comments} {/if}\r\n\r\n=================================\r\n\r\n{/foreach}\r\n\r\n\r\n\r\n{$adminsignature}   ','','','0','','','',1,1,'{$orderid}- Order ID , {$imei} - IMEI No, {$note} - Notes , {$comments} - Comments , {$ordercredit} - Credit For Order , {$model} - Model Name , {$provider} - Provider Name , {$mep} - MEP , {$pin} - PIN Number , {$kbh} - KBH , {$prd} - PRD , {$type}- Type ,{$reference} - Reference , {$locks} - Locks ,{$comments}- User Comments,\r\n{$reply}- Admin Reply',0,0,'',0),(65,'resellerstore','New User registered on Store','New User registered on your store','Dear {$user}\r\n\r\n \r\n\r\nNew user just sign up on your site\r\n\r\nDetails\r\n\r\n==========\r\n\r\nUsername : {$username}\r\n\r\nFirst Name: {$firstname}\r\n\r\nLast Name : {$lastname}\r\n\r\nPhone No : {$phonenumber}\r\n\r\nEmail : {$email}','','','0','','','',1,0,'{$username}-Registered users Username,\r\n{$firstname}-Registered users Firstname,\r\n{$lastname}-Registered users Last Name,\r\n{$phonenumber}-Reistered users Phonenumber,\r\n{$email}-Reistered users E-mail',0,0,'',0),(68,'general','When direct order placed','Your order for {$service} has been process successfully','Dear Customer\r\n\r\n         Your order for {$service} has been process successfully\r\n         to complete your order open this link {$link}\r\n         and submit further details like your IMEI made  (dial *#06# to get the IMEI)\r\n etc..\r\n\r\n         we process your order shortly once we got your details .\r\n\r\n         if you are not  open link directly just copy and pest this link in your browser\r\n\r\n\r\n\r\n{$adminsignature}     ','','','0','','','',1,0,'',0,0,'',0),(70,'general','Return request for order','Return Request','<p>Dear {$username}</p>\r\n<p> </p>\r\n<p>Return Request for your order</p>\r\n<p>details are ...</p>\r\n<p> </p>\r\n<p>Items : {$product}</p>\r\n<p>Reason: {$reason}</p>\r\n<p>Action : {$action}</p>\r\n<p>Comment: {$comment}</p>\r\n<p>Please send Item to :</p>\r\n<p>Return Id : {$refid}</p>\r\n<p><span>{$address}</span></p>\r\n{if $status}\r\nStatus : {$status}\r\n{/if}\r\n<p> </p>','','','','','','',0,0,'',0,0,'',0),(67,'general','Withdrawal Request Accepted','Withdrawal Request has been processed','Dear {$user}\r\n\r\nYour withdrawal Request for amount {$amount}  has been processed\r\n\r\nDetails \r\n================\r\nAmount          : {$amount}\r\nTransaction ID : {$transactionid}\r\nGateway          : {$gateway